<?php require_once 'auth.php'; require_admin(); $pdo=db(); if(!$pdo){header('Location: users.php?error=Chưa kết nối MySQL');exit;} $id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$password=$_POST['password']??'';$role=$_POST['role']??'editor';$active=isset($_POST['active'])?1:0;if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($role,['admin','editor'],true)||(!$id&&strlen($password)<8)){header('Location: user-form.php?error=Vui lòng kiểm tra lại thông tin');exit;}try{if($id){$sql='UPDATE users SET name=?,email=?,role=?,active=?'.($password!==''?',password_hash=?':'').' WHERE id=?';$params=[$name,$email,$role,$active];if($password!=='')$params[]=password_hash($password,PASSWORD_DEFAULT);$params[]=$id;$pdo->prepare($sql)->execute($params);if($id===(int)current_admin()['id'])$_SESSION['admin_user']=array_merge(current_admin(),['name'=>$name,'email'=>$email,'role'=>$role,'active'=>$active]);$msg='Đã lưu người dùng';}else{$pdo->prepare('INSERT INTO users(name,email,password_hash,role,active) VALUES(?,?,?,?,?)')->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role,$active]);$msg='Đã tạo người dùng';}header('Location: users.php?ok='.urlencode($msg));}catch(Throwable $e){header('Location: user-form.php?error='.urlencode('Không thể lưu, email có thể đã tồn tại'));}
